@bp.route("/")
@login_required
def home():
    if not current_user.profile_complete:
        return redirect(url_for("profile.setup"))
    # Son kilo güncellemesi zamanı (kilo butonu "hatırlatma" parıltısı için —
    # cihazlar arası tutarlı olsun diye sunucudan, localStorage yerine).
    last_checkin = WeeklyCheckIn.query.filter_by(user_id=current_user.id)\
        .order_by(WeeklyCheckIn.created_at.desc()).first()
    last_weight_update = (last_checkin.created_at.isoformat() + "Z") if last_checkin else ""
    return render_template("index.html",
        username=current_user.username,
        profile_picture=current_user.avatar_src,
        streak_count=current_user.streak_count or 0,
        last_weight_update=last_weight_update,
    )


@bp.route("/log", methods=["POST"])
@login_required
def log_progress():
    data = request.get_json(silent=True) or {}
    weight = data.get("weight")
    note = data.get("note", "")

    if not weight:
        return jsonify({"error" : t("route.weight_required")}), 400
    
    try:
        weight = float(weight)
    except (ValueError, TypeError):  # liste/dict gibi JSON tipleri TypeError verir → 500 yerine 400 (D5)
        return jsonify({"error" : t("route.weight_numeric")}), 400
    
    entry = WeeklyLog(
        user_id = current_user.id,
        weight=weight,
        note=note
    )
    db.session.add(entry)
    db.session.commit()

    # Önceki kayıtlarla karşılaştırma
    previous = WeeklyLog.query.filter_by(user_id=current_user.id)\
    .order_by(WeeklyLog.created_at.desc())\
    .offset(1).first()

    message = t("route.weight_logged", weight=weight)
    if previous:
        diff = round(weight - previous.weight , 1)
        if diff < 0:
            message += t("route.weight_lost", diff=abs(diff))
        elif diff > 0:
            # D6: '=' yerine '+=' — aksi halde kilo ALMA dalında "kg kaydedildi"
            # önekı düşüyor (diğer dallar += ile ekliyor).
            message += t("route.weight_gained", diff=abs(diff))
        else:
            message += t("route.weight_same")
    return jsonify({"message" : message})


