@bp.route("/checkin", methods=["POST"])
@login_required
@limiter.limit(AI_RATELIMIT, key_func=_user_or_ip_key)
@limiter.limit(BEDROCK_RATELIMIT, key_func=_user_or_ip_key)  # generate_checkin_feedback Sonnet'te: daha sıkı tavan
def checkin():
    data = request.get_json(silent=True) or {}

    weight = data.get("weight")
    if not weight:
        return jsonify({"error": t("route.weight_required")}), 400

    try:
        weight = float(weight)
    except (ValueError, TypeError):  # liste/dict gibi JSON tipleri TypeError verir → 500 yerine 400 (D5)
        return jsonify({"error": t("route.weight_numeric")}), 400

    # Bozuk/eksik payload ("yogunluk": "" veya "yüksek") int() ile 500 atardı;
    # _to_int güvenle varsayılana düşer.
    yogunluk    = _to_int(data.get("yogunluk", 3), 3)
    fatigue     = _to_int(data.get("fatigue", 3), 3)
    overload    = data.get("progressive_overload", "kismen")
    if overload not in ("evet", "hayir", "kismen"):
        overload = "kismen"
    uyku        = _to_int(data.get("uyku_kalitesi", 3), 3)
    beslenme    = _to_int(data.get("beslenme_uyumu", 3), 3)
    note        = data.get("note", "")

    # Önceki check-in'i al
    previous = WeeklyCheckIn.query.filter_by(user_id=current_user.id)\
        .order_by(WeeklyCheckIn.created_at.desc())\
        .first()

    # Son oturum bilgilerini al
    last_session = UserSession.query.filter_by(user_id=current_user.id)\
        .order_by(UserSession.created_at.desc())\
        .first()

    goal = last_session.goal if last_session else "genel sağlık"

    # İlerleme hesapla
    prev_weight = previous.weight if previous else None
    days_passed = None
    if previous:
        # Geçen gün sayısı Istanbul gün sınırına göre (CLAUDE.md) — ham UTC farkı
        # gece-yarısı yakınında bir gün kayardı (F1.2).
        days_passed = (app_today() - app_date_of(previous.created_at)).days

    # AI koç geri bildirimi
    coach_feedback = generate_checkin_feedback(
        current_user.username, weight, prev_weight, days_passed,
        goal, yogunluk, fatigue, overload, uyku, beslenme, note,
        language=current_user.language
    )

    entry = WeeklyCheckIn(
        user_id=current_user.id,
        weight=weight,
        yogunluk=yogunluk,
        fatigue=fatigue,
        progressive_overload=overload,
        uyku_kalitesi=uyku,
        beslenme_uyumu=beslenme,
        note=note,
        coach_feedback=coach_feedback
    )
    db.session.add(entry)
    db.session.commit()

    # "Haftalık Check-in" görevini ver (günde bir kez; zaten claimliyse None — 1.1).
    quest_result = complete_quest_for_user(current_user.id, "checkin_done")

    resp = {
        "message": t("route.checkin_saved"),
        "coach_feedback": coach_feedback
    }
    if quest_result:
        resp["quest_awarded"] = quest_result
    return jsonify(resp)


